def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    strong_prev = 0.0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) > strong_prev:
                    strong_prev = float(bid)

    if not alive:
        return float(min(budget, 18.0 if hp > 3 else 45.0))

    supply_units = int(supply // WATER_REQ)
    contested = supply_units <= 1

    urgent = hp <= 3 or no_water >= 2
    semi_urgent = hp <= 5 or no_water >= 1

    if strong_prev >= 130:
        pressure = 'extreme'
    elif strong_prev >= 105:
        pressure = 'high'
    elif strong_prev >= 75:
        pressure = 'medium'
    else:
        pressure = 'low'

    if contested:
        if urgent:
            target = max(96.0, strong_prev + 2.0)
        elif pressure == 'extreme':
            target = 34.0
        elif pressure == 'high':
            target = max(82.0, strong_prev + 1.5)
        elif pressure == 'medium':
            target = max(68.0, strong_prev + 1.5)
        else:
            target = 58.0
    else:
        if urgent:
            target = max(62.0, strong_prev * 0.78 if strong_prev > 0 else 62.0)
        elif semi_urgent:
            target = 42.0 if pressure in ('extreme', 'high') else 36.0
        else:
            target = 24.0 if pressure in ('extreme', 'high') else 18.0

    days_left = max(0, 10 - int(day_context['day']) + 1)
    reserve = days_left * 18.0
    if urgent:
        reserve = days_left * 10.0
    affordable = max(0.0, budget - reserve)
    if affordable <= 0:
        affordable = min(budget, 28.0 if not urgent else 55.0)

    bid = min(float(budget), float(target), float(affordable))

    if urgent and bid < 55.0:
        bid = min(float(budget), max(55.0, strong_prev + 1.0 if strong_prev > 0 else 55.0))

    if hp >= 8 and no_water == 0 and contested and pressure == 'extreme':
        bid = min(bid, 26.0)

    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = int(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        cap = DAILY_SALARY * 0.4
        return min(my_budget, cap)

    # Extract yesterday bids from immediate previous_trace only
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Baseline from yesterday: try to undercut the high bidders but stay competitive
    # If we saw high pressure, slightly increase.
    if prev_bids:
        sorted_bids = sorted(prev_bids)
        # Use median-ish and lower-quantile to avoid overbidding
        n = len(sorted_bids)
        lower = sorted_bids[int((n - 1) * 0.33)]
        upper = sorted_bids[int((n - 1) * 0.66)]
        max_prev = max(sorted_bids)

        # Pressure indicator
        high_pressure = max_prev >= DAILY_SALARY * 0.85
        mid_pressure = upper >= DAILY_SALARY * 0.75

        # Supply scaling: when supply is tight, bid more
        # Map supply in [MIN_SUPPLY, MAX_SUPPLY] to [0,1]
        denom = float(MAX_SUPPLY - MIN_SUPPLY)
        if denom <= 0.0:
            tightness = 0.5
        else:
            tightness = (float(MAX_SUPPLY) - supply) / denom
            if tightness < 0.0:
                tightness = 0.0
            if tightness > 1.0:
                tightness = 1.0

        # HP/budget urgency
        hp_urgent = my_hp <= 2 or my_no_water_days >= 2
        budget_tight = my_budget <= DAILY_SALARY * 0.8

        # Target bid
        if hp_urgent or budget_tight:
            target = DAILY_SALARY * (0.85 if high_pressure else 0.65)
        else:
            # Compete near the lower cluster plus a small premium
            premium = 5.0 + 10.0 * tightness
            if high_pressure:
                premium += 8.0
            elif mid_pressure:
                premium += 4.0
            target = lower + premium

        # Keep within reasonable bounds
        min_bid = DAILY_SALARY * 0.35
        max_bid = DAILY_SALARY * (0.95 if high_pressure else 0.75)
        target = max(min_bid, min(target, max_bid))

        return min(my_budget, target)

    # No valid previous bids: simple policy
    denom = float(MAX_SUPPLY - MIN_SUPPLY)
    if denom <= 0.0:
        tightness = 0.5
    else:
        tightness = (float(MAX_SUPPLY) - supply) / denom
        if tightness < 0.0:
            tightness = 0.0
        if tightness > 1.0:
            tightness = 1.0

    if my_hp <= 2 or my_no_water_days >= 2:
        base = DAILY_SALARY * 0.85
    else:
        base = DAILY_SALARY * (0.55 + 0.2 * tightness)

    return min(my_budget, base)

